import{_ as e,o as a,c as n,Q as t}from"./chunks/framework.b67c47e6.js";const g=JSON.parse('{"title":"Claude connector (MCP)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mcp/index.md","filePath":"guide/mcp/index.md","lastUpdated":1789635248000}'),o={name:"guide/mcp/index.md"},s=t('<h1 id="claude-connector-mcp" tabindex="-1">Claude connector (MCP) <a class="header-anchor" href="#claude-connector-mcp" aria-label="Permalink to &quot;Claude connector (MCP)&quot;">​</a></h1><p>Connect Claude to produuz.it and ask about your own production in plain language: <em>which panels in the Meerhoven project are still waiting on parts</em>, <em>what did line 2 finish yesterday</em>, <em>which batches are late</em>.</p><p>The connector uses <strong>MCP</strong>, the standard Claude uses to talk to other systems. You add it once, sign in with your produuz.it account in the browser, and Claude answers from your company&#39;s live data.</p><nav class="table-of-contents"><ul><li><a href="#what-it-can-and-cannot-do">What it can and cannot do</a></li><li><a href="#what-you-need">What you need</a></li><li><a href="#adding-the-connector">Adding the connector</a><ul><li><a href="#in-claude-ai">In claude.ai</a></li><li><a href="#in-claude-code">In Claude Code</a></li><li><a href="#in-claude-desktop">In Claude Desktop</a></li></ul></li><li><a href="#the-consent-screen">The consent screen</a></li><li><a href="#things-you-can-ask">Things you can ask</a></li><li><a href="#disconnecting">Disconnecting</a></li><li><a href="#documentation-without-an-account">Documentation without an account</a></li><li><a href="#security">Security</a></li></ul></nav><h2 id="what-it-can-and-cannot-do" tabindex="-1">What it can and cannot do <a class="header-anchor" href="#what-it-can-and-cannot-do" aria-label="Permalink to &quot;What it can and cannot do&quot;">​</a></h2><p>The connector is <strong>read-only</strong>. That is not a setting you can change and it is not a promise about how it is used: there is no way to write through it at all.</p><table><thead><tr><th>It can</th><th>It cannot</th></tr></thead><tbody><tr><td>Read projects, batches, panels, modules and parts</td><td>Change, create or delete anything</td></tr><tr><td>Read production status and kit completeness</td><td>Start or finish production</td></tr><tr><td>Read dashboards, today&#39;s timeline and issues</td><td>Touch a checklist or a proof</td></tr><tr><td>Create temporary download links for your files</td><td>Change any setting</td></tr><tr><td>Search this documentation</td><td>See any other company&#39;s data</td></tr></tbody></table><p>Everything it reads is scoped to <strong>your company</strong>, exactly like the app. It reads with your account, so it sees what your account is entitled to see and nothing beyond it.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><p>An <strong>MCP licence</strong> on your user account. Licences are per person and your company has a number of seats, like the Android or Tekla ones.</p><p>Ask your company administrator to give you a seat: <strong>Company → Users → Licences → MCP</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Taking the licence away ends the connection. If somebody leaves, removing their seat cuts their connector off within the hour, without anybody having to find and revoke a token.</p></div><h2 id="adding-the-connector" tabindex="-1">Adding the connector <a class="header-anchor" href="#adding-the-connector" aria-label="Permalink to &quot;Adding the connector&quot;">​</a></h2><h3 id="in-claude-ai" tabindex="-1">In claude.ai <a class="header-anchor" href="#in-claude-ai" aria-label="Permalink to &quot;In claude.ai&quot;">​</a></h3><ol><li>Open <strong>Settings → Connectors → Add custom connector</strong>.</li><li>Paste the URL:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">https://back.produuz.it/api/v2/mcp</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">https://back.produuz.it/api/v2/mcp</span></span></code></pre></div></li><li>Claude opens a produuz.it page asking you to approve the connection. Check the account and company it names, read what it will be able to do, and press <strong>Allow</strong>.</li></ol><p>On <strong>Team</strong> and <strong>Enterprise</strong> plans an owner adds the connector once for the whole organisation, and each person then signs in with their own account. Everybody sees their own company&#39;s data, never each other&#39;s.</p><h3 id="in-claude-code" tabindex="-1">In Claude Code <a class="header-anchor" href="#in-claude-code" aria-label="Permalink to &quot;In Claude Code&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">claude</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">mcp</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">add</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--transport</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">http</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">produuzit</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">https://back.produuz.it/api/v2/mcp</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--scope</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">user</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">claude</span><span style="color:#24292E;"> </span><span style="color:#032F62;">mcp</span><span style="color:#24292E;"> </span><span style="color:#032F62;">add</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--transport</span><span style="color:#24292E;"> </span><span style="color:#032F62;">http</span><span style="color:#24292E;"> </span><span style="color:#032F62;">produuzit</span><span style="color:#24292E;"> </span><span style="color:#032F62;">https://back.produuz.it/api/v2/mcp</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--scope</span><span style="color:#24292E;"> </span><span style="color:#032F62;">user</span></span></code></pre></div><p>Then run <code>/mcp</code> inside Claude Code and follow the browser prompt to sign in.</p><h3 id="in-claude-desktop" tabindex="-1">In Claude Desktop <a class="header-anchor" href="#in-claude-desktop" aria-label="Permalink to &quot;In Claude Desktop&quot;">​</a></h3><p>Same as claude.ai: <strong>Settings → Connectors → Add custom connector</strong>, with the same URL.</p><h2 id="the-consent-screen" tabindex="-1">The consent screen <a class="header-anchor" href="#the-consent-screen" aria-label="Permalink to &quot;The consent screen&quot;">​</a></h2><p>Before anything is connected, produuz.it shows you what you are about to approve:</p><ul><li><strong>which application</strong> is asking, and whether produuz.it has reviewed it;</li><li><strong>which account and company</strong> is being connected — worth a look, because many people have more than one account and the wrong one would show Claude the wrong company;</li><li>that the access is <strong>read only</strong>;</li><li>what it will be able to read, in plain words;</li><li>what it will <strong>never</strong> be able to do;</li><li>where you will be sent back to, and how to disconnect later.</li></ul><p>If you do not have an MCP licence, the screen says so rather than failing with an error code.</p><h2 id="things-you-can-ask" tabindex="-1">Things you can ask <a class="header-anchor" href="#things-you-can-ask" aria-label="Permalink to &quot;Things you can ask&quot;">​</a></h2><p>Once connected, ask Claude in your own words. It picks the right lookups itself.</p><ul><li><em>Which panels in project 24031 are not built yet, and how many are waiting on parts?</em></li><li><em>What did each station finish today?</em></li><li><em>Show me the open issues on the Meerhoven project.</em></li><li><em>Which batches on line 2 are behind their delivery date?</em></li><li><em>How many panels were finished each week over the last quarter?</em></li><li><em>What does &quot;kitted parts&quot; mean in produuz.it?</em></li></ul><p>That last one works because the connector can also read this documentation. When a produuz.it word needs explaining, Claude looks it up here rather than guessing.</p><h2 id="disconnecting" tabindex="-1">Disconnecting <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;Disconnecting&quot;">​</a></h2><p>Two ways, either is enough:</p><ul><li><strong>In produuz.it</strong> — <strong>Account → Connected apps</strong> lists everything you have approved, when you approved it and when it was last used. Press <strong>Disconnect</strong>.</li><li><strong>In Claude</strong> — remove the connector.</li></ul><p>Disconnecting in produuz.it takes effect immediately, whether or not the other side cooperates.</p><h2 id="documentation-without-an-account" tabindex="-1">Documentation without an account <a class="header-anchor" href="#documentation-without-an-account" aria-label="Permalink to &quot;Documentation without an account&quot;">​</a></h2><p>There is a second connector that serves only this documentation and needs no produuz.it account at all:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">https://back.produuz.it/api/v2/mcp/docs</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">https://back.produuz.it/api/v2/mcp/docs</span></span></code></pre></div><p>It is useful if you are evaluating produuz.it, or helping somebody who has not been given an account yet. It only reaches these public pages — never any company&#39;s data.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>You sign in on produuz.it. The application you are connecting never sees your password.</li><li>The permission is bound to <strong>your account and your company</strong>, and is checked on every single request rather than once at connection time.</li><li>Access is <strong>read only</strong> end to end.</li><li>Download links are a separate permission, asked for only when one is actually needed, because a link can be opened by anybody who holds it until it expires.</li><li>You can revoke everything from <strong>Account → Connected apps</strong> at any time.</li></ul>',39),i=[s];function c(r,l,d,p,h,u){return a(),n("div",null,i)}const m=e(o,[["render",c]]);export{g as __pageData,m as default};
